// GÉNÉRÉ depuis docs/template/03 Accueil v2.dc.html, section A01S, cadre 390 px.
// Ne pas modifier à la main : relancer `node tools/generate-screens.mjs`.
//
// Les styles en ligne sont ceux de la maquette, à l'identique. Le conteneur
// extérieur, lui, est fluide : la maquette le fige à 390 px, ce qui ne
// serait pas responsive.
import { Fragment } from 'react';
import type { A01SData } from '../a01/data';

export function A01SMobile(props: A01SData) {
  const { onAjouterOption, onSondageAnonyme, onSondageApresVote, onSondageMultiple, onSondageQuestion, onValiderSondage, sondageAnonyme, sondageApresVote, sondageBloque, sondageDurees, sondageMultiple, sondageOptions, sondageQuestion } = props;

  return (
    <>

      <div style={{ position: "fixed", inset: "0", background: "rgba(22,33,29,.55)" }} data-modal-overlay=""></div>
      <div style={{ position: "fixed", left: "0", right: "0", bottom: "0", height: "90%", background: "#fff", borderRadius: "28px 28px 0 0", padding: "10px 16px 26px", display: "flex", flexDirection: "column", gap: "14px", maxHeight: "calc(100vh - 24px)", overflow: "hidden" }} data-modal-panel="">
        <button type="button" aria-label="Fermer" data-modal-close="" style={{ alignSelf: "center", width: "40px", height: "5px", borderRadius: "999px", background: "#DDE3E0", border: "none", padding: "10px 24px", font: "inherit", cursor: "pointer", boxSizing: "content-box", marginTop: "0", backgroundClip: "content-box" }}></button>
        <h2 id="a01s-titre" style={{ margin: "0", fontSize: "18px", fontWeight: "800" }}>Créer un sondage</h2>
        <div data-fenetre-contenu="" style={{ flex: "1", minHeight: "0", overflowY: "auto", display: "flex", flexDirection: "column", gap: "14px" }}><div><div style={{ fontSize: "12.5px", fontWeight: "700", marginBottom: "8px" }}>Question</div><div style={{ height: "50px", borderRadius: "14px", border: "1px solid #E6EBE9", padding: "0 14px", display: "flex", alignItems: "center", fontSize: "14.5px", fontWeight: "600" }}><input type="text" value={sondageQuestion} onChange={onSondageQuestion} placeholder="Quelle date pour le repas partagé ?" aria-label="Question du sondage" data-sondage-question="" style={{ flex: "1", minWidth: "0", border: "none", background: "transparent", font: "inherit", color: "#16211D", outline: "none", padding: 0 }} /></div></div>
  <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}><div style={{ fontSize: "12.5px", fontWeight: "700" }}>Options <span style={{ color: "#8A958F", fontWeight: "500" }}>· 2 à 5</span></div>{(sondageOptions ?? []).map((o, oIndex) => (
<Fragment key={oIndex}><div style={{ display: "flex", alignItems: "center", gap: "8px", marginBottom: "8px" }}><input type="text" value={o.texte} onChange={o.onTexte} placeholder="Une réponse" aria-label="Réponse du sondage" data-sondage-option="" style={{ flex: "1", height: "48px", borderRadius: "14px", border: "1px solid #E6EBE9", background: "#fff", padding: "0 14px", fontSize: "14px", font: "inherit", color: "#16211D", outline: "none" }} />{o.retirable ? (<button type="button" onClick={o.onRetirer} aria-label="Retirer cette réponse" style={{ width: "32px", height: "32px", border: "none", background: "transparent", cursor: "pointer", padding: 0, color: "#5D6B66" }}><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18M6 6l12 12" /></svg></button>) : null}</div></Fragment>))}<button type="button" onClick={onAjouterOption} data-sondage-ajouter="" style={{ display: "flex", alignItems: "center", gap: "8px", paddingLeft: "28px", height: "40px", fontSize: "13.5px", fontWeight: "700", color: "#16785E", fontFamily: "inherit", cursor: "pointer", border: "none" }}><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#16785E" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 5v14M5 12h14" /></svg>Ajouter une option</button></div>
  <div><div style={{ fontSize: "12.5px", fontWeight: "700", marginBottom: "8px" }}>Durée</div><div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: "4px", background: "#EEF2F0", borderRadius: "14px", padding: "4px" }}>{(sondageDurees ?? []).map((d, dIndex) => (
<Fragment key={dIndex}><button type="button" onClick={d.onPick} aria-pressed={d.on} style={{ height: "38px", borderRadius: "11px", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "13px", fontWeight: "700", border: "none", font: "inherit", cursor: "pointer", background: d.bg, color: d.fg }}>{d.label}</button></Fragment>))}</div></div>
  <div style={{ borderTop: "1px solid #EAEEEC" }}><div style={{ display: "flex", alignItems: "center", gap: "12px", padding: "10px 0" }}><div style={{ flex: "1" }}><div style={{ fontSize: "13.5px", fontWeight: "700" }}>Plusieurs réponses possibles</div></div><button type="button" role="switch" aria-checked={sondageMultiple} onClick={onSondageMultiple} aria-label="Plusieurs réponses possibles" data-sondage-multiple="" style={{ width: "46px", height: "26px", borderRadius: "999px", background: sondageMultiple ? "#16785E" : "#CBD5D1", position: "relative", flexShrink: "0", border: "none", padding: 0, cursor: "pointer" }}><span style={{ position: "absolute", top: "3px", left: sondageMultiple ? "calc(100% - 23px)" : "3px", width: "20px", height: "20px", borderRadius: "999px", background: "#fff" }}></span></button></div><div style={{ display: "flex", alignItems: "center", gap: "12px", padding: "10px 0" }}><div style={{ flex: "1" }}><div style={{ fontSize: "13.5px", fontWeight: "700" }}>Résultats visibles après le vote</div><div style={{ fontSize: "12px", color: "#5D6B66", marginTop: "2px" }}>Évite d’influencer les premiers votants.</div></div><button type="button" role="switch" aria-checked={sondageApresVote} onClick={onSondageApresVote} aria-label="Résultats visibles après le vote" data-sondage-apres-vote="" style={{ width: "46px", height: "26px", borderRadius: "999px", background: sondageApresVote ? "#16785E" : "#CBD5D1", position: "relative", flexShrink: "0", border: "none", padding: 0, cursor: "pointer" }}><span style={{ position: "absolute", top: "3px", left: sondageApresVote ? "calc(100% - 23px)" : "3px", width: "20px", height: "20px", borderRadius: "999px", background: "#fff" }}></span></button></div><div style={{ display: "flex", alignItems: "center", gap: "12px", padding: "10px 0" }}><div style={{ flex: "1" }}><div style={{ fontSize: "13.5px", fontWeight: "700" }}>Vote anonyme</div><div style={{ fontSize: "12px", color: "#5D6B66", marginTop: "2px" }}>Seul le total est affiché, pas les noms.</div></div><button type="button" role="switch" aria-checked={sondageAnonyme} onClick={onSondageAnonyme} aria-label="Vote anonyme" data-sondage-anonyme="" style={{ width: "46px", height: "26px", borderRadius: "999px", background: sondageAnonyme ? "#16785E" : "#CBD5D1", position: "relative", flexShrink: "0", border: "none", padding: 0, cursor: "pointer" }}><span style={{ position: "absolute", top: "3px", left: sondageAnonyme ? "calc(100% - 23px)" : "3px", width: "20px", height: "20px", borderRadius: "999px", background: "#fff" }}></span></button></div></div>
        <div style={{ flex: "1" }}></div>
        </div><button type="button" onClick={onValiderSondage} disabled={sondageBloque} data-sondage-valider="" style={{ height: "52px", borderRadius: "14px", background: "#16785E", color: "#fff", border: "none", font: "inherit", fontSize: "15px", fontWeight: "700", flexShrink: "0", cursor: "pointer", opacity: sondageBloque ? ".55" : "1" }}>Ajouter à la publication</button>
      </div>
    
    </>
  );
}
